{
  "headline": "Oxytocin is not on FDA's current shortage list as of 2026-10-21; an earlier shortage was first posted 2022-09-23 and is now resolved",
  "headline_cites": ["D15"],
  "sentences": [
    {
      "text": "FDA's records show oxytocin is not on the current shortage list as of 2026-10-21; the prior shortage was first posted 2022-09-23 and has since been resolved.",
      "cites": ["D15"]
    },
    {
      "text": "The prior shortage posting followed FDA inspections at Fresenius Kabi USA LLC (FEI 1450022) that ended 2020-05-18 and 2022-06-30, both classified OAI, 858 and 85 days before the 2022-09-23 posting.",
      "cites": ["D3", "D4"]
    },
    {
      "text": "A later inspection at the same plant ended 2023-08-24 and was classified VAI, 335 days after the shortage posting.",
      "cites": ["D5"]
    },
    {
      "text": "A second Fresenius Kabi plant (FEI 3001833549) had an inspection ending 2023-10-13 classified VAI, 385 days after the posting.",
      "cites": ["D6"]
    },
    {
      "text": "The preferred alternative per P&T is oxytocin 10 units/mL from Par Health USA, LLC (NDC 42023011602), approved by Sam Rivera, MD on 2026-04-16, with dose and volume recalculation and pharmacist verification required.",
      "cites": ["D16", "E29"]
    },
    {
      "text": "The Par Health product label identifies PH HEALTH as the manufacturing plant with a sponsor-only link.",
      "cites": ["E5"]
    },
    {
      "text": "A secondary option is oxytocin 10 USP units/mL from Fresenius Kabi USA, LLC (NDC 63323001210), approved by Riley Brooks, PharmD on 2026-01-24, also requiring recalculation and pharmacist verification.",
      "cites": ["D17", "E30"]
    }
  ]
}
